package pro.celikom.nativeprobe.identitydiag;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.OffsetDateTime;import java.util.*;import org.json.*;
/** Replays only policy inputs from an owner-supplied report; the report itself is never packaged. */
public class TestReportReplay {
 public static void main(String[] args)throws Exception {JSONObject catalog=new JSONObject(new String(Files.readAllBytes(Paths.get(args[1])),StandardCharsets.UTF_8));long now=0;Set<String> verified=new LinkedHashSet<>();for(String line:Files.readAllLines(Paths.get(args[0]),StandardCharsets.UTF_8)){JSONObject row;try{row=new JSONObject(line);}catch(Exception e){continue;}String event=row.optString("event");JSONObject data=row.optJSONObject("data");if(data==null)continue;if("run_start".equals(event))now=OffsetDateTime.parse(data.getString("utc")).toInstant().toEpochMilli();if(!"hybrid_identity".equals(event))continue;JSONObject o=data.getJSONObject("observation");String title=o.getString("title");if(!Arrays.asList("Вспышка","Ау").contains(title))continue;Map<String,Object> own=HybridIdentity.own(catalog,title,o.getString("artist"),o.getLong("durationMs"),now);Map<String,Object> learned=LogStore.map("status","NO_MATCH");Map<String,Object> decision=HybridIdentity.decide(null,own,learned,false);String expected=title.equals("Вспышка")?"38436680":"144530503";if(!"OWN_CATALOGUE_HINT".equals(decision.get("method"))||!expected.equals(decision.get("candidateTrackId"))||!Boolean.FALSE.equals(decision.get("playbackAuthorized")))throw new AssertionError(title+": "+decision);verified.add(title);}if(verified.size()!=2)throw new AssertionError("Both report cases required");System.out.println("PASS: owner-report replay: "+verified+" resolve to confirmed-only historical hints under album HTTP451; no cached playback authorization");}
}
